     1	#!/usr/bin/env node
     2	
     3	/**
     4	 * Asset Sanitizer & Metadata Cleaner
     5	 *
     6	 * Strips EXIF, XMP, IPTC, GPS, and private device metadata from all
     7	 * project assets in assets/ and assets/backgrounds/, removes junk files
     8	 * like .DS_Store, and embeds a clean creator tag.
     9	 */
    10	
    11	const fs = require("node:fs");
    12	const path = require("node:path");
    13	
    14	const ROOT_DIR = path.resolve(__dirname, "..");
    15	const ASSETS_DIR = path.join(ROOT_DIR, "assets");
    16	const APP_NAME = require(path.join(ROOT_DIR, "app.json")).expo.name;
    17	
    18	function cleanJpeg(buffer) {
    19	  if (buffer.length < 4 || buffer[0] !== 0xff || buffer[1] !== 0xd8) {
    20	    return buffer;
    21	  }
    22	
    23	  const chunks = [Buffer.from([0xff, 0xd8])];
    24	  let offset = 2;
    25	
    26	  const commentText = APP_NAME;
    27	  const commentLen = 2 + Buffer.byteLength(commentText);
    28	  const commentBuf = Buffer.alloc(4 + Buffer.byteLength(commentText));
    29	  commentBuf[0] = 0xff;
    30	  commentBuf[1] = 0xfe;
    31	  commentBuf[2] = (commentLen >> 8) & 0xff;
    32	  commentBuf[3] = commentLen & 0xff;
    33	  commentBuf.write(commentText, 4, "utf8");
    34	
    35	  let insertedComment = false;
    36	
    37	  while (offset < buffer.length) {
    38	    if (buffer[offset] !== 0xff) break;
    39	    while (buffer[offset] === 0xff && offset < buffer.length) offset++;
    40	    const marker = buffer[offset];
    41	    offset++;
    42	
    43	    if (marker === 0xd9) {
    44	      chunks.push(Buffer.from([0xff, 0xd9]));
    45	      break;
    46	    }
    47	
    48	    if (marker === 0xda) {
    49	      if (!insertedComment) {
    50	        chunks.push(commentBuf);
    51	        insertedComment = true;
    52	      }
    53	      chunks.push(Buffer.from([0xff, 0xda]));
    54	      chunks.push(buffer.subarray(offset));
    55	      break;
    56	    }
    57	
    58	    if (offset + 2 > buffer.length) break;
    59	    const len = (buffer[offset] << 8) | buffer[offset + 1];
    60	    const payload = buffer.subarray(offset + 2, offset + len);
    61	
    62	    // Strip metadata markers:
    63	    // 0xE1: APP1 (EXIF, XMP)
    64	    // 0xE2: APP2 (FlashPix/ICC)
    65	    // 0xED: APP13 (Photoshop IPTC)
    66	    // 0xEE: APP14 (Adobe)
    67	    // 0xFE: COM (Previous comments)
    68	    const isMetadataMarker = [0xe1, 0xe2, 0xed, 0xee, 0xfe].includes(marker);
    69	
    70	    if (!isMetadataMarker) {
    71	      chunks.push(Buffer.from([0xff, marker, (len >> 8) & 0xff, len & 0xff]));
    72	      chunks.push(payload);
    73	    }
    74	
    75	    offset += len;
    76	  }
    77	
    78	  return Buffer.concat(chunks);
    79	}
    80	
    81	function cleanPng(buffer) {
    82	  const PNG_SIG = Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]);
    83	  if (buffer.length < 8 || !buffer.subarray(0, 8).equals(PNG_SIG)) {
    84	    return buffer;
    85	  }
    86	
    87	  const chunks = [PNG_SIG];
    88	  let offset = 8;
    89	
    90	  const STRIP_CHUNKS = new Set([
    91	    "eXIf",
    92	    "iTXt",
    93	    "tEXt",
    94	    "zTXt",
    95	    "tIME",
    96	    "pHYs",
    97	    "gAMA",
    98	    "cHRM",
    99	    "sRGB",
   100	    "iCCP",
   101	    "dSIG",
   102	    "prVW",
   103	  ]);
   104	
   105	  while (offset + 8 <= buffer.length) {
   106	    const length = buffer.readUInt32BE(offset);
   107	    const type = buffer.subarray(offset + 4, offset + 8).toString("ascii");
   108	    const totalChunkLen = 4 + 4 + length + 4;
   109	
   110	    if (offset + totalChunkLen > buffer.length) break;
   111	
   112	    if (!STRIP_CHUNKS.has(type)) {
   113	      chunks.push(buffer.subarray(offset, offset + totalChunkLen));
   114	    }
   115	
   116	    offset += totalChunkLen;
   117	    if (type === "IEND") break;
   118	  }
   119	
   120	  return Buffer.concat(chunks);
   121	}
   122	
   123	function getFilesRecursively(dir) {
   124	  if (!fs.existsSync(dir)) return [];
   125	  const entries = fs.readdirSync(dir, { withFileTypes: true });
   126	  const files = [];
   127	
   128	  for (const entry of entries) {
   129	    const fullPath = path.join(dir, entry.name);
   130	    if (entry.name === ".DS_Store" || entry.name.startsWith("._")) {
   131	      fs.unlinkSync(fullPath);
   132	      console.log(`  🗑️  Removed junk file: ${path.relative(ASSETS_DIR, fullPath)}`);
   133	      continue;
   134	    }
   135	    if (entry.isDirectory()) {
   136	      files.push(...getFilesRecursively(fullPath));
   137	    } else if (/\.(jpe?g|png|webp)$/i.test(entry.name)) {
   138	      files.push(fullPath);
   139	    }
   140	  }
   141	
   142	  return files;
   143	}
   144	
   145	const { execSync } = require("node:child_process");
   146	
   147	function stripExtendedAttributes(filePath) {
   148	  if (process.platform === "darwin") {
   149	    try {
   150	      execSync(`xattr -c "${filePath}"`, { stdio: "ignore" });
   151	    } catch {
   152	      // Ignore errors if xattr is not supported on target filesystem
   153	    }
   154	  }
   155	}
   156	
   157	function run() {
   158	  console.log(`\n🧹 ${APP_NAME} Asset Sanitizer`);
   159	  console.log("━".repeat(45));
   160	
   161	  const files = getFilesRecursively(ASSETS_DIR);
   162	  let totalSavedBytes = 0;
   163	  let cleanedCount = 0;
   164	
   165	  for (const filePath of files) {
   166	    const relPath = path.relative(ASSETS_DIR, filePath);
   167	    stripExtendedAttributes(filePath);
   168	
   169	    const originalBuf = fs.readFileSync(filePath);
   170	    let cleanedBuf = originalBuf;
   171	
   172	    if (/\.(jpe?g)$/i.test(filePath)) {
   173	      cleanedBuf = cleanJpeg(originalBuf);
   174	    } else if (/\.png$/i.test(filePath)) {
   175	      cleanedBuf = cleanPng(originalBuf);
   176	    }
   177	
   178	    const saved = originalBuf.length - cleanedBuf.length;
   179	    if (saved > 0 || !originalBuf.equals(cleanedBuf)) {
   180	      fs.writeFileSync(filePath, cleanedBuf);
   181	      stripExtendedAttributes(filePath);
   182	      totalSavedBytes += Math.max(0, saved);
   183	      cleanedCount++;
   184	      console.log(
   185	        `  ✨ Sanitized: ${relPath} (${saved > 0 ? `saved ${saved} B` : "metadata stripped"})`
   186	      );
   187	    } else {
   188	      console.log(`  ✓  Clean: ${relPath}`);
   189	    }
   190	  }
   191	
   192	  console.log("━".repeat(45));
   193	  console.log(`✅ Completed: ${files.length} assets checked, ${cleanedCount} stripped.`);
   194	  if (totalSavedBytes > 0) {
   195	    console.log(`📦 Total metadata stripped: ${(totalSavedBytes / 1024).toFixed(2)} KB\n`);
   196	  } else {
   197	    console.log(`📦 All assets are clean with zero residual metadata.\n`);
   198	  }
   199	}
   200	
   201	run();
     1	// Writes the Google Play "What's new" file for one version from webpage/changelog.html.
     2	// Usage: node scripts/play-release-notes.mjs <version> <output-dir>
     3	import { mkdirSync, readFileSync, writeFileSync } from "node:fs";
     4	import { join } from "node:path";
     5	
     6	// Google Play rejects release notes longer than 500 characters per language.
     7	const PLAY_NOTES_LIMIT = 500;
     8	
     9	const ENTITIES = {
    10	  "&amp;": "&",
    11	  "&lt;": "<",
    12	  "&gt;": ">",
    13	  "&quot;": '"',
    14	  "&#39;": "'",
    15	  "&nbsp;": " ",
    16	};
    17	
    18	function plainText(html) {
    19	  return html
    20	    .replace(/<[^>]+>/g, " ")
    21	    .replace(/&[a-z0-9#]+;/gi, (entity) => ENTITIES[entity] ?? entity)
    22	    .replace(/\s+/g, " ")
    23	    .trim();
    24	}
    25	
    26	export function releaseNotesFor({ html, version }) {
    27	  const sections = html.split(/<h2>/).slice(1);
    28	  const section = sections.find((part) => part.slice(0, part.indexOf("</h2>")).trim() === version);
    29	  if (!section) throw new Error(`No changelog section for ${version} in webpage/changelog.html`);
    30	
    31	  const items = [...section.matchAll(/<li>([\s\S]*?)<\/li>/g)].map((match) => {
    32	    const tag = match[1].match(/<span class="changelog-tag[^"]*">([^<]+)<\/span>/)?.[1];
    33	    const text = plainText(match[1].replace(/<span class="changelog-tag[^"]*">[^<]+<\/span>/, ""));
    34	    return tag ? `• ${tag}: ${text}` : `• ${text}`;
    35	  });
    36	  if (items.length === 0) throw new Error(`Changelog section for ${version} has no items`);
    37	
    38	  // Keep whole items only; the website changelog stays the complete record.
    39	  const more = "• More fixes and improvements.";
    40	  const kept = [];
    41	  for (const [index, item] of items.entries()) {
    42	    const reserve = index < items.length - 1 ? more.length + 1 : 0;
    43	    if ([...kept, item].join("\n").length + reserve > PLAY_NOTES_LIMIT) break;
    44	    kept.push(item);
    45	  }
    46	  if (kept.length === 0)
    47	    throw new Error(`First changelog item for ${version} exceeds ${PLAY_NOTES_LIMIT} characters`);
    48	  return kept.length < items.length ? [...kept, more].join("\n") : kept.join("\n");
    49	}
    50	
    51	if (import.meta.url === `file://${process.argv[1]}`) {
    52	  const [version, outputDir] = process.argv.slice(2);
    53	  if (!version || !outputDir)
    54	    throw new Error("Usage: play-release-notes.mjs <version> <output-dir>");
    55	  const html = readFileSync(new URL("../webpage/changelog.html", import.meta.url), "utf8");
    56	  const notes = releaseNotesFor({ html, version });
    57	  mkdirSync(outputDir, { recursive: true });
    58	  writeFileSync(join(outputDir, "whatsnew-en-US"), `${notes}\n`);
    59	  console.log(notes);
    60	}
    );
  });
});

test("foreign keys are enforced only after migrations complete", async () => {
  const database = new DatabaseSync(":memory:");
  const base = createAdapter(database);
  const foreignKeyStatesDuringMigrations = [];
  const db = {
    ...base,
    withTransactionAsync: async (task) => {
      // Migrations run inside transactions; capture the constraint state they see.
      foreignKeyStatesDuringMigrations.push(
        database.prepare("PRAGMA foreign_keys").get().foreign_keys
      );
      return base.withTransactionAsync(task);
    },
  };

  await initializeDatabaseSchema(db);

  // A future migration must be able to use SQLite's rename/copy/drop table
  // rebuild, which enforced foreign keys from entry_tags would block; the
  // pragma also cannot be toggled inside the migration's own transaction.
  assert.deepEqual(foreignKeyStatesDuringMigrations, [0]);
  assert.equal(database.prepare("PRAGMA foreign_keys").get().foreign_keys, 1);
});

test("identifies unreferenced media without false matches on prefixes or shared references", async () => {
  const database = new DatabaseSync(":memory:");
  const db = createAdapter(database);
  await initializeDatabaseSchema(db);

  // Entries store bare filenames; "prefix_shared-photo.jpg" must not count as a
  // reference to "shared-photo.jpg".
  database
    .prepare(
      `INSERT INTO entries (id, created_at, updated_at, images, audios, attachments)
       VALUES (?, ?, ?, ?, ?, ?)`
    )
    .run("entry-1", 1000, 1000, JSON.stringify(["shared-photo.jpg"]), null, null);

  database
    .prepare(
      `INSERT INTO entries (id, created_at, updated_at, images, audios, attachments)
       VALUES (?, ?, ?, ?, ?, ?)`
    )
    .run(
      "entry-2",
      2000,
      2000,
      JSON.stringify(["prefix_shared-photo.jpg"]),
      JSON.stringify(["audio-note.m4a"]),
      JSON.stringify([{ uri: "document.pdf", name: "Doc" }])
    );

  // Mirrors filterUnreferencedMedia: a quoted-filename instr match across media columns.
  const checkReferenced = (filename) => {
    const needle = `"${filename}"`;
    return Boolean(
      database
        .prepare(
          `SELECT 1 FROM entries
            WHERE instr(images, ?) > 0
               OR instr(audios, ?) > 0
               OR instr(attachments, ?) > 0
            LIMIT 1`
        )
        .get(needle, needle, needle)
    );
  };

  assert.equal(checkReferenced("shared-photo.jpg"), true);
  assert.equal(checkReferenced("prefix_shared-photo.jpg"), true);
  assert.equal(checkReferenced("audio-note.m4a"), true);
  assert.equal(checkReferenced("document.pdf"), true);
  assert.equal(checkReferenced("deleted-photo.jpg"), false);

  // When entry-1 is deleted, shared-photo.jpg becomes unreferenced while entry-2 media remains referenced
  database.prepare("DELETE FROM entries WHERE id = ?").run("entry-1");
  assert.equal(checkReferenced("shared-photo.jpg"), false);
  assert.equal(checkReferenced("prefix_shared-photo.jpg"), true);
});
